// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *CheckLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, CheckLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (bank_account_no, entry_status, check_no)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$bank_account_status_check", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index bank_account_status_check: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (bank_account_ledger_entry_no, entry_status)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$bank_ledger_entry_status", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index bank_ledger_entry_status: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (bank_account_no, check_date)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$bank_account_check_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index bank_account_check_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (bank_account_no, open)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$bank_account_open", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index bank_account_open: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Check_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	var keys []sift.Key
	for _, spec := range checkLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, CheckLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, CheckLedgerEntryTableName, keys)
}

// checkLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func checkLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *CheckLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, CheckLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range checkLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, CheckLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: CheckLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, CheckLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

