// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *CheckLedgerEntry) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, CheckLedgerEntryTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "entry_no":
			column = "entry_no"
		case "bank_account_ledger_entry_no":
			column = "bank_account_ledger_entry_no"
		case "amount":
			column = "amount"
		case "statement_line_no":
			column = "statement_line_no"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Check_Ledger_Entry", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Check_Ledger_Entry.%s: %w", column, err)
		}
		switch column {
		case "entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Check_Ledger_Entry.%s: %w", column, err)
			}
			t.Entry_no = int(f)
		case "bank_account_ledger_entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Check_Ledger_Entry.%s: %w", column, err)
			}
			t.Bank_account_ledger_entry_no = int(f)
		case "amount":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Check_Ledger_Entry.%s: %w", column, err)
			}
			t.Amount = d
		case "statement_line_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Check_Ledger_Entry.%s: %w", column, err)
			}
			t.Statement_line_no = int(f)
		}
	}
	return nil
}

